  "literacy.tutorial.step1Desc": "टाइप करने दी लोड़ नेईं। बस अपने शिल्प दा वर्णन करदे होई इक छोटा सा आवाज़ नोट रिकार्ड करो। साढ़ा एआई लिस्टिंग दी लिपिबद्धता ते लिखदा ऐ।",
  "literacy.tutorial.step2Title": "2. स्वचालित ऐ स्टूडियो प्रकाश व्यवस्था",
  "literacy.tutorial.step2Desc": "अपने मोबाइल पर सादे फोटो खिच्चो। साढ़ा ऐ व्यस्त वर्कशॉप दी पृष्ठभूमि गी साफ करदा ऐ ते प्राकृतिक रोशनी गी संतुलित करदा ऐ।",
  "literacy.tutorial.step3Title": "3. उचित कीमत सलाहकार",
  "literacy.tutorial.step3Desc": "अस तुंदी कच्चे माल ते रोजमर्रा दे श्रम लागत दी गणना करने आं तां जे तुस कदें बी अपनी उचित कमाई थमां घट्ट नेईं बिकदे।",
  "literacy.tutorial.step4Title": "4. प्रत्यक्ष बैंक भुगतान",
  "literacy.tutorial.step4Desc": "खरीददार डीबीटी दे राहें सीधे तुंदे सत्यापन बैंक खाते च भुगतान करदे न। शून्य बिचौलिया फीस।",
  "literacy.tutorial.close": "मिल गया, शुरू करदे हां",
  "literacy.tutorial.open": "एह् किस चाल्ली कम्म करदा ऐ",
  "literacy.demo.start": "डेमो लिस्टिंग आज़माइश करो",
  "literacy.demo.tag": "नमूना लिस्टिंग दा डेमो",
  "literacy.sahayak.mode": "सहायक हेल्प मोड",
  "literacy.sahayak.tooltip.camera": "सुझाव: दिन दी रोशनी च स्थिर रक्खो। साढ़ा एआई अपने आप टुकड़े गी अलग करी देग ते वर्कशॉप दी बैकग्राउंड गी हटाई देग।",
  "literacy.sahayak.tooltip.pricing": "सुझाऽ: एह् ग्रीन बेसलाइन सरकारी न्यूनतम कारीगर मुआवजे थमां मती तुंदी जिंदगी जीने दी मजदूरी दी गारंटी दिंदी ऐ।",
