  "pdp.care.dryClean": "सिर्फ ड्राई क्लीन करो। मलमल च फोड़ी सिद्धी धुप्प थमां दूर रक्खो।",
  "pdp.care.handWash": "ठंडे पाणी ते हल्के साबुन सैत आसती हत्थें धोओ। छांह् च सुखाओ।",
  "pdp.care.wipe": "मुलायम सुक्खे कपड़े सैत पूंझो। ध्यान सैत रक्खो; डिशवाशर च नेईं पाओ।",
  "pdp.care.polish": "कदि-कदि सुक्खे कपड़े सैत चमकाओ। पाणी ते तेजाबी क्लीनरें थमां बचाओ।",
  "pdp.care.dry": "सिल्ल थमां दूर रक्खो। मुलायम ब्रश सैत धूड़ हटाओ।",
  "pdp.care.frame": "शीशे पिच्छै फ्रेम करो। सिल्ली कंडा ते सिद्धी धुप्प थमां दूर रक्खो।",
  "pdp.care.default": "ध्यान सैत रक्खो। मुलायम सुक्खे कपड़े सैत आसती साफ करो।",
  "pdp.review.1.title": "फोटुएं थमां बी सोह्ना",
  "pdp.review.1.body": "{craft} दा कम्म नेड़े दिक्खणे पर होर बी बारीक ऐ। छोटी-छोटी असमानतां दस्सदियां न जे एह् हत्थें बणाया। बड़ा ध्यान सैत पैक कीता था।",
  "pdp.review.2.title": "हर रुपे दे लायक",
  "pdp.review.2.body": "एह् जाणियै जे पैसे सिद्धे {artisan} गी जांदे न, फैसला सोह्जा होई गेआ। म्यूज़ियम जनेह् क्वालिटी।",
  "pdp.review.3.title": "सोह्णा, थोड़ा लेट आया",
  "pdp.review.3.body": "अंदाज़े थमां तीन दिन लेट आया, पर शिल्पकारै संदेश भेजियै कारण दस्सी दित्ता। चीज़ अपने-आपे च कमाल ऐ।",
  "pdp.review.4.title": "मुहर जांची, सब असली",
  "pdp.review.4.body": "मिलणे पर प्रमाणिकता रिकार्ड जांचा ते सूची सैत पूरा मिलदा था। आखिर च ऑनलाइन शिल्प खरीदी पर भरोसा होया।",
  "pdp.review.5.title": "बद्धिया, पर नाप जांच लो",
  "pdp.review.5.body": "बद्धिया कारीगरी, पर सोचणे थमां छोटी। आर्डर करने थमां पैह्ले विवरण सारणी च नाप पढ़ी लो।",
  "pdp.qa.1.q": "एह् हत्थें बणाया ऐ जां मशीनै?",
  "pdp.qa.1.a": "पूरी तरह हत्थें बणाया। जीआई टैग ते प्रमाणिकता मुहर दो’नें तकनीक दी पुश्टी करदे न।",
  "pdp.qa.2.q": "क्या मैं होर रंग मंग सकदा/सकदी आं?",
  "pdp.qa.2.aMto": "हां, आर्डर पर बणने आह्ली चीज़ें च बदलाव होई सकदा — आर्डर नोट च लिखो।",
  "pdp.qa.2.aReady": "एह् तैयार स्टॉक दी चीज़ ऐ, इसलेई रंग दिखाए गेदे मताबक ई न। खास आर्डर आस्तै शिल्पकार गी संदेश भेजो।",
  "pdp.qa.3.q": "भेजणे आस्तै एह् किस्सै पैक कीती जांदी ऐ?",
  "pdp.qa.3.a": "कपड़े च, फिर बबल रैप च लपेटियै दोहरी कंडा आह्ले डब्बे च। कमज़ोर चीज़ें आस्तै खास क्रेट।",
  "pdp.qa.4.q": "धोणे बाद रंग फिक्का पई जाग?",
  "pdp.qa.4.a": "कुदरती रंग साल-दर-साल थोड़े मुलायम होई जांदे न, एह् आम गल्ल ऐ। रंग बचाणे आस्तै संभाल दियां हदायतें गी मन्नो।",
  "pdp.storefront.bio": "{name} {district} च {craft} दा कम्म करदा ऐ ते ग्राहकें गी सिद्धा बेचदा ऐ।",
