  "pdp.trivia.heading": "की तुसें जाणदे ओ?",
  "craft.weaving.funFact": "बनारसी ब्रोकेड बुनकरें गी बारीक जरी दे कम्म आळी इक रेशमी साड़ी बनाणे च इक म्हीने तगर दा बकत लगी सकदा ऐ।",
  "craft.block-printing.funFact": "इक अजरख ब्लॉक-प्रिंट डिजाइन गी अपणे पूरे गहरे रंग तगर पुज्जने आस्तै रंगाई, धोआई ते सुखाणे दे 16 पड़ाऽ तगर दी लोड़ पेई सकदी ऐ।",
  "craft.pottery.funFact": "निजामाबाद दे कल्ले मिट्टी दे भांडेआं गी उंदी चमकदी कल्ली चमक धुऐं कन्नै भरोई, आक्सीजन-रहित भट्ठी च पकाणे कन्नै मिलदी ऐ, कुसै रंग जां ग्लेज कन्नै नेईं।",
  "craft.metalwork.funFact": "बिदरी कारीगरी च चांदी दी जड़ाई इक इसी मिश्रित धात च कीती जंदी ऐ जिसगी बीदर किले नेड़े मिलने आळी खास मिट्टी कन्नै कल्ला कीता जंदा ऐ।",
  "craft.woodwork.funFact": "चन्नापटना दे लकड़ी दे खिलौने अज बी 200 साल पुराणी खराद तकनीक पर बनस्पती रंगें कन्नै पालिश कीते जंदे न।",
  "craft.embroidery.funFact": "लखनऊ दे इक चिकनकारी कपड़े उप्पर सूई कन्नै कीते दर्जनें बक्ख-बक्ख कढ़ाई दे टांके होई सकदे न।",
  "craft.painting.funFact": "रवायती मधुबनी चित्रकारी बिहार च जनानिएं आसेआ अपणे घरें दी मिट्टी दी भित्तें उप्पर बणाईयां तस्वीरें कन्नै शुरू होई ही।",
  "craft.basketry.funFact": "मूंज घास दी टोकरी बुनाई इक जंगली हड़ प्रभावत इलाके दी घास गी टिकाऊ, पूरी तरहां जैव-विघटनशील घरेलू सामान च बदली दिंदी ऐ।",
  "craft.jewellery.funFact": "कटक दी चांदी दी तारकशी बालें थमां बी झीणे चांदी दे तारै कन्नै घड़ी जंदी ऐ।",
  "craft.leather.funFact": "कोल्हापुरी चप्पलां रवायती तौरा उप्पर पूरी तरहां हथ्थें कन्नै सिलियां जंदियां न, बिना कुसै कील जां मशीन दी सलाई दे।",
  "craft.stone.funFact": "आगरा दे पत्थर-जड़ाई करने आळे कारीगर अज बी सैई पिएत्रा दूरा तकनीक बरतदे न जेह्ड़ी ताजमहल गी सजांदी ऐ।",
  "craft.bamboo.funFact": "इक बांस दा बूटा सिर्फ 3-5 सालें च गै कारीगरी बरतणे आस्तै त्यार होई सकदा ऐ, जेह्ड़ा सख्त लकड़ी दे रुक्खें थमां मते जल्दी ऐ।",
  "tips.modal.title": "अज्जै दी सलाह",
  "tips.modal.gotIt": "समझ आई गेआ",
  "tips.priceFloor": "हमेशा अपणी लागत सीमा थमां उप्पर कीमत रक्खो — कच्चा माल, तुंदा बकत ते प्लेटफार्म फीस — मंदी दे म्हीने च बी।",
  "tips.trackIncome": "हर इक बिक्री लिखो, भामें उ छोटी गै हो। इक सादी आमदनी रिकार्ड तुसेंगी कमजोर मौसम आस्तै योजना बणाणे ते कर्ज आस्तै कमाई साबित करने च मदद करदा ऐ।",
  "tips.bulkOrders": "थोक ते संस्थागत आर्डर पक्के तौरा उप्पर ते पैह्लें गै भुगतान करदे न। अपणी समर्था ते त्यारी दा बकत अपडेट रक्खो तां जो ग्राहक तुसेंगी लब्भी सकन।",
  "tips.photoQuality": "साफ, खरी लोऽ आळियां ते मते कोणें थमां लियां तस्वीरें आळियां लिस्टिंगां छेती बिकदियां न। कुदरती लोऽ फ्लैश थमां खरी कम्म करदी ऐ।",
  "tips.respondFast": "जिसलै तुस इक्क दिन दे अंदर सवालें दा जवाब दिंदे ओ तां ग्राहकें दे आर्डर पूरा करने दी बक बधी जंदी ऐ।",
  "tips.saveSavings": "हर भुगतान दा इक छोटा हिस्सा बचत दे तौरा उप्पर बक्ख रक्खो — 5% बी जुड़ी करी आर्डरें बिच तुंदी मदद करदा ऐ।",
  "tips.giPremium": "GI टैग मूल थाह्र दा सबूत ऐ जिस उप्पर ग्राहक भरोसा करदे न। प्रमाणित चीजें दी कीमत अक्सर मती रक्खी जाई सकदी ऐ — अपणी चीज़ दी कीमत घट्ट नेईं आंकणी।",
  "tips.restockEarly": "कच्चा माल मुक्कने थमां पैह्लें गै फिरी मंगाणा शुरू करो, खासतौर पर त्योहार ते ब्याह दे मौसम थमां पैह्लें जिसलै मंग बधी जंदी ऐ।",
  "tips.clusterSupport": "तुंदा क्लस्टर समन्वयक थोक सामग्री खरीदने ते सिखलाई च मदद करी सकदा ऐ — कुसै समस्या दे गंभीर होने थमां पैह्लें गै संपर्क करो।",
  "tips.storySells": "कहाणी आळियां चीजें आस्तै ग्राहक मता भुगतान करदे न। अपणी तकनीक जां कारीगरी दे इतिहास बारै इक छोटा जेहा नोट अपणी लिस्टिंग च जोड़ो।",
